//  Stock.swift — the film and paper library, read from the bundle.
//
//  The desktop's `StockCatalog.swift`. The catalogue is generated by
//  `tools/gen_catalog.py` from the engine's own profiles and that script's
//  names, so the picker cannot list a stock the engine does not have, and a
//  profile with no name fails the generator. `id` is the engine's profile id:
//  an internal key that goes on the wire and never reaches the page.

import SwiftUI

struct Stock: Codable, Identifiable, Hashable, Sendable {
    let id: String
    /// "Kodak Portra 400": Info, Settings, anywhere there is room.
    let name: String
    /// "Portra 400": cards, the library line.
    let shortName: String
    /// "colour negative", "slide (positive)", "cine negative", "b&w negative", "colour paper",
    /// "cine print film", "b&w paper".
    let kind: String
    let stage: String          // "filming" | "printing"
    let use: String            // "still" | "cine"
    let type: String?          // "negative" | "positive"
    let targetPrint: String?
    let iso: Int?
    /// "#rrggbb": the card's swatch and the library's dot.
    let swatch: String
    /// A black-and-white stock: a film with one silver emulsion, or a silver
    /// paper (the profile's `channel_model` is `bw`). Absent on a colour stock.
    let monochrome: Bool?
    /// A black-and-white film's own grain: what the Grain strength's 1 is on
    /// it, as the `grain_amount` at which the engine renders the granularity
    /// its maker publishes. Absent on every other stock, where it is 1.
    let grain: Double?
    /// A silver paper's filter pack — the enlarger's C, M, Y — which the host
    /// sends because the engine's own table has no row for the paper.
    let neutralPack: [Double]?

    /// A stock as the catalogue's file has it, or as a check makes one up.
    init(id: String, name: String, shortName: String, kind: String, stage: String, use: String = "still",
         type: String? = "negative", targetPrint: String? = nil, iso: Int? = nil, swatch: String = "#808080",
         monochrome: Bool? = nil, grain: Double? = nil, neutralPack: [Double]? = nil) {
        self.id = id; self.name = name; self.shortName = shortName; self.kind = kind; self.stage = stage
        self.use = use; self.type = type; self.targetPrint = targetPrint; self.iso = iso; self.swatch = swatch
        self.monochrome = monochrome; self.grain = grain; self.neutralPack = neutralPack
    }

    var isMonochrome: Bool { monochrome ?? false }
    var isFilm: Bool { stage == "filming" }
    var isPaper: Bool { stage == "printing" }
    var isCine: Bool { use == "cine" }
    /// A reversal (slide) film. A positive is already a viewable image, so
    /// printing one onto paper is an operation nobody wants (the desktop's note).
    var isPositive: Bool { type == "positive" }
    var color: Color { Color(hexString: swatch) }
    /// The name as the film's edge prints it: capitals.
    var edgeName: String { name.uppercased() }
    /// "ISO 400", for a film card.
    var isoText: String? { iso.map { "ISO \($0)" } }
}

struct StockCatalog: Sendable {
    let stocks: [Stock]

    static let shared: StockCatalog =
        Bundle.main.url(forResource: "StockCatalog", withExtension: "json").flatMap(StockCatalog.init(contentsOf:))
            ?? StockCatalog(stocks: [])

    init(stocks: [Stock]) { self.stocks = stocks }

    /// The catalogue as `tools/gen_catalog.py` writes it (a check reads the
    /// repository's own file, where there is no bundle).
    init?(contentsOf url: URL) {
        guard let data = try? Data(contentsOf: url),
              let decoded = try? JSONDecoder().decode(Wrapper.self, from: data) else { return nil }
        stocks = decoded.stocks
    }

    private struct Wrapper: Decodable { let stocks: [Stock] }

    /// In the picker's order: the catalogue's own.
    var films: [Stock] { stocks.filter(\.isFilm) }
    var papers: [Stock] { stocks.filter(\.isPaper) }
    func stock(_ id: String) -> Stock? { stocks.first { $0.id == id } }

    /// Whether `paper` is the paper `film` was made for — an honest pairing
    /// against an approximation (API-SPEC §2).
    func isDeclaredPairing(film: String, paper: String) -> Bool {
        stock(film)?.targetPrint == paper
    }

    /// "Porta 400 · Supera Enduro": a frame's stock line. **A slide film has
    /// no paper to name** — "Ectochrome 100 · scanned" — whatever paper the
    /// frame still holds for the next negative.
    func pairText(film: String, paper: String) -> String {
        let f = stock(film)?.shortName ?? film
        if isSlide(film) { return "\(f) · \(L(shown: Self.scannedWord))" }
        guard let p = stock(paper)?.shortName else { return f }
        return "\(f) · \(p)"
    }

    /// The same line for a frame's own settings: a negative that is scanned
    /// (a desktop edit's *No Print Profile*) says so too.
    func pairText(_ params: FilmParams) -> String {
        guard !isScanned(params) else { return "\(stock(params.filmStock)?.shortName ?? params.filmStock) · \(L(shown: Self.scannedWord))" }
        // The Digital Intermediate takes the paper's place, and the line says so (2.2.1).
        if params.digitalIntermediateActive(filmIsPositive: false) {
            return "\(stock(params.filmStock)?.shortName ?? params.filmStock) · \(L("Digital Intermediate"))"
        }
        return pairText(film: params.filmStock, paper: params.printStock)
    }

    static let scannedWord = "scanned"
}

// MARK: - the film decides whether there is a print

//  A slide is the picture itself: it is scanned, not printed. Until 2026-10-09
//  the host's film cards set the film and nothing else, so a slide film stayed
//  tied to whatever paper the frame had and was printed on it — the engine does
//  that without complaint, and nobody wants it (the owner, 2026-10-09: "the
//  positive profiles are still tied to a printing paper which should not happen
//  again").
//
//  The desktop's rule (`Session.selectFilmStock`, `applyFilmStageRule`,
//  `selectPrintStock`; SpektraLab `unpublished-revision`), with what the host's own page
//  changes: `scan_film` is a field of its own beside `print_stock`, so the
//  compatible paper a frame had survives while a slide is selected. Selecting
//  a negative brings its recommendation (owner, 2026-10-15); copying an
//  explicit pair and validating a library edit preserve its chosen paper.
//  It is held in three places, so that no caller can walk past it:
//
//  1. **the pick** (`load(film:)`, `print(on:)`): the host has no control that
//     scans a negative, so loading a film decides both ways — a slide scans, a
//     negative prints on its recommended paper — and a paper is refused
//     under a slide;
//  2. **every edit that enters** (`heldToItsFilm`): a paste, a library read
//     from disk, a session's change. One way only: a slide is scanned. A
//     negative keeps what it has, so a desktop edit that scans a negative is
//     carried unchanged;
//  3. **the wire** (`wire(for:)`): whatever an edit says, the engine is never
//     told to print a slide.
//
//  **Silver on silver, colour on colour** (2026-10-09) is the same kind of
//  rule, held in the same three places. A black-and-white film has one silver
//  emulsion and prints on a silver paper; the engine prints it on a colour
//  paper without complaint, orange (no filter pack exists for the pair), and a
//  colour negative on the silver paper as a grey nobody asked for. The
//  desktop's rule (`StockCatalog.canPrint`, `Session.selectFilmStock`,
//  `selectPrintStock`; SpektraLab `adb3eb0d`):
//
//  1. **the pick**: a selected film brings its recommended paper; a paper
//     of the other kind is refused;
//  2. **every edit that enters**: a film and a paper of two kinds are never
//     carried; the film stays and its own paper comes with it;
//  3. **the wire**: what a black-and-white film on its paper needs that no
//     edit holds (`silver(_:into:)`).
extension StockCatalog {
    func isSlide(_ film: String) -> Bool { stock(film)?.isPositive ?? false }

    /// Whether `paper` can print `film` at all: silver on silver, colour on
    /// colour. A stock the catalogue does not know rules nothing out — a
    /// library kept by a later build is not rewritten by this one.
    func canPrint(film: String, on paper: String) -> Bool {
        guard let f = stock(film), let p = stock(paper) else { return true }
        return f.isMonochrome == p.isMonochrome
    }

    /// Product recommendation for a newly selected film. The profile's
    /// targetPrint remains its calibration metadata; recommendations do not
    /// modify the emulsion, curves or engine filter tables.
    func ownPaper(of film: String) -> String? {
        guard let f = stock(film) else { return nil }
        let recommended: String?
        switch film {
        case "kodak_gold_200", "kodak_ektar_100": recommended = "kodak_supra_endura"
        case "kodak_ultramax_400": recommended = "kodak_ultra_endura"
        default: recommended = f.targetPrint
        }
        if let own = recommended, let p = stock(own), p.isPaper, p.isMonochrome == f.isMonochrome { return own }
        return papers.first { $0.isMonochrome == f.isMonochrome }?.id
    }

    /// The UI dot means recommended, independently of the paper currently selected.
    func isRecommendedPairing(film: String, paper: String) -> Bool {
        !isSlide(film) && ownPaper(of: film) == paper
    }

    /// `paper` if it can print `film`, the film's own paper otherwise.
    func paper(printing film: String, kept paper: String) -> String {
        canPrint(film: film, on: paper) ? paper : (ownPaper(of: film) ?? paper)
    }

    /// Whether these settings are scanned and not printed: a slide, or a
    /// negative whose edit says so.
    func isScanned(_ params: FilmParams) -> Bool { params.scanFilm || isSlide(params.filmStock) }

    /// A frame's parameters as the engine is told them: `FilmParams.fullDelta`
    /// of the settings held to their film, so that everything the wire derives
    /// from the scan (the calibrated range, Scene Placement under a digital
    /// intermediate) follows it too. The one thing `FilmParams` cannot know is
    /// which films are slides.
    func wire(for params: FilmParams) -> [String: ParamValue] {
        let held = params.heldToItsFilm(catalog: self)
        var wire = held.fullDelta
        silver(held, into: &wire)
        return wire
    }

    /// What a black-and-white film and a silver paper need on the wire that an
    /// edit does not hold, because only the catalogue knows which stocks they
    /// are. The engine enforces none of it (`ENGINE-WIRING.md` §4.7, with what
    /// it does without each); they are the desktop app's rules (`Params.swift`,
    /// SpektraLab `adb3eb0d` and `0bca29da`):
    ///
    /// - **the grain is one layer** on a black-and-white film, whatever the
    ///   setting: the three sub-layers are the colour films' model;
    /// - **the film's own grain**: the Grain strength multiplies the amount at
    ///   which the engine renders the film's published granularity, clamped to
    ///   the wire's range — Tri-Ex's ruler is at its end from 1.18;
    /// - **no Extended Dynamic Range on a silver paper**, which has no
    ///   calibration for it: the engine refuses the open by name;
    /// - **the paper's filter pack** for a silver pair, and only then: the
    ///   engine's table has no row for a silver paper, and a session coming
    ///   from a colour pair would keep that pair's. Going back, the engine
    ///   takes the colour pair's own row again, so nothing is sent for it.
    ///
    /// **The enlarger's two filter shifts are sent as the frame has them**, as
    /// on the desktop. On this paper they are its grade and not a colour:
    /// measured through the engine on 2026-10-09, on every one of the four
    /// films, Yellow +1 is a softer and darker print (Tri-Ex: the steepest
    /// 0.44 D a stop becomes 0.33, the mid grey 0.74 D becomes 0.92) and
    /// Magenta +1 a harder and lighter one (0.62 D a stop, 0.53 D), neutral
    /// throughout. So the Print tab's rulers say that there (`PrintPanel`),
    /// and not "→ blue".
    ///
    /// No colour frame's wire moves: every line is conditional on a stock the
    /// catalogue marks `monochrome`.
    func silver(_ held: FilmParams, into wire: inout [String: ParamValue]) {
        if let film = stock(held.filmStock), film.isMonochrome {
            wire["grain_sublayers_active"] = .bool(false)
            wire["grain_amount"] = .double((held.effects.grain * (film.grain ?? 1)).clamped(to: EffectStrengths.grainRange))
        }
        guard let paper = stock(held.printStock), paper.isMonochrome else { return }
        wire["extended_dynamic_range"] = .bool(false)
        if isMonochrome(held.filmStock), let pack = paper.neutralPack, pack.count == 3 {
            wire["c_filter_neutral"] = .double(pack[0])
            wire["m_filter_neutral"] = .double(pack[1])
            wire["y_filter_neutral"] = .double(pack[2])
        }
    }

    func isMonochrome(_ id: String) -> Bool { stock(id)?.isMonochrome ?? false }

    /// The pair a new frame takes from the one that was chosen — Settings'
    /// *New frames*, the last frame developed —
    /// held to the rule a frame's own is: **the paper is one that prints it**
    /// (a film chosen alone, as the carousel chooses, brings its own). One
    /// place, so that no page that reads the pair can name one a new frame
    /// would not get.
    func newFramePair(film: String, paper: String) -> (film: String, paper: String) {
        (film, self.paper(printing: film, kept: paper))
    }

    /// A black-and-white film on a silver paper, printed.
    func isSilverPrint(_ params: FilmParams) -> Bool {
        !isScanned(params) && isMonochrome(params.filmStock) && isMonochrome(params.printStock)
    }
}

extension FilmParams {
    /// Selecting a film brings its recommended print. A later explicit paper
    /// choice is kept by heldToItsFilm and by library reads, until another
    /// film is selected. Slides are scanned and retain a compatible dormant
    /// paper. Constructors copying an explicit pair pass recommendingPaper:
    /// false; that validates the pair without replacing its chosen paper.
    mutating func load(film id: String, catalog: StockCatalog = .shared, recommendingPaper: Bool = true) {
        filmStock = id
        scanFilm = catalog.isSlide(id)
        printStock = scanFilm || !recommendingPaper ? catalog.paper(printing: id, kept: printStock)
            : (catalog.ownPaper(of: id) ?? catalog.paper(printing: id, kept: printStock))
        if recommendingPaper { digitalIntermediate = false }
    }

    /// Print on a paper, as a paper card does. False, and nothing changed,
    /// under a slide film, and for a paper of the other kind — a colour paper
    /// under a black-and-white film, the silver paper under a colour one: the
    /// gate is here and not only in the dimmed cards.
    @discardableResult
    mutating func print(on paper: String, catalog: StockCatalog = .shared) -> Bool {
        guard !catalog.isSlide(filmStock), catalog.canPrint(film: filmStock, on: paper) else { return false }
        printStock = paper
        scanFilm = false
        digitalIntermediate = false
        return true
    }

    /// These settings with the rules applied: a slide is scanned, and a paper
    /// that cannot print the film gives way to the film's own.
    func heldToItsFilm(catalog: StockCatalog = .shared) -> FilmParams {
        let scan = scanFilm || catalog.isSlide(filmStock)
        let paper = catalog.paper(printing: filmStock, kept: printStock)
        guard scan != scanFilm || paper != printStock else { return self }
        var p = self
        p.scanFilm = scan
        p.printStock = paper
        return p
    }
}

// MARK: - what a page asks of the rule

//  The pages that offer a paper (the develop page's Print tab, the picker for
//  new frames) ask here, so that a card or a row is dimmed for the reason the
//  model refuses it and for no other.
extension StockCatalog {
    /// Why a paper waits under a film, in the desktop's own words for it
    /// (as the black-and-white brief of 2026-10-09 gives them); nil where the
    /// paper prints the film. A slide's papers wait for another reason, and
    /// all of them: the pages say that themselves.
    func whyNotPrinted(film: String, on paper: String) -> String? {
        guard !canPrint(film: film, on: paper) else { return nil }
        return isMonochrome(film) ? Self.colourPaperWaits : Self.silverPaperWaits
    }

    static var colourPaperWaits: String { L("a colour paper: a black-and-white film prints on a black-and-white paper") }
    static var silverPaperWaits: String { L("a black-and-white paper: choose a black-and-white film to print on it") }

    /// Whether Grain's Sub-layers moves anything: not on a black-and-white
    /// film, whose grain the wire sends as one layer whatever the setting.
    func grainIsLayered(on film: String) -> Bool { !isMonochrome(film) }
}

/// A film and a paper being chosen together, where no frame holds them yet —
/// the picker for new frames and for an import. Kept a pair a frame could
/// have, by the rules a frame's own settings are kept by (`FilmParams.load`,
/// `print(on:)`).
struct StockPair: Equatable, Sendable {
    var film: String
    var paper: String

    /// A film's row. Selecting a negative brings its recommended paper.
    mutating func load(film id: String, catalog: StockCatalog = .shared) {
        film = id
        paper = catalog.isSlide(id) ? catalog.paper(printing: id, kept: paper)
            : (catalog.ownPaper(of: id) ?? catalog.paper(printing: id, kept: paper))
    }

    /// A paper's row. False, and nothing changed, under a slide film and for
    /// a paper of the other kind.
    @discardableResult
    mutating func print(on id: String, catalog: StockCatalog = .shared) -> Bool {
        guard !catalog.isSlide(film), catalog.canPrint(film: film, on: id) else { return false }
        paper = id
        return true
    }
}

extension FrameEdit {
    func heldToItsFilm(catalog: StockCatalog = .shared) -> FrameEdit {
        let held = params.heldToItsFilm(catalog: catalog)
        guard held != params else { return self }
        var e = self
        e.params = held
        return e
    }

    /// An edit as it enters a frame — a page's change, a paste: its film
    /// decides whether there is a print, and the film's long edge is the one
    /// this frame's own photograph makes (`FilmParams.heldToItsPhoto`).
    func held(to photo: PixelSize, catalog: StockCatalog = .shared) -> FrameEdit {
        let held = params.heldToItsFilm(catalog: catalog).heldToItsPhoto(photo)
        guard held != params else { return self }
        var e = self
        e.params = held
        return e
    }
}
